### Test whether a value is an unsigned decimal integer.
number::_is-non-negative-integer() {
  if [[ "$#" -ne 1 ]]; then
    return 64
  fi

  ( [[ "$1" =~ ^[0-9]+$ ]] )
}

### Test whether a value is a positive unsigned decimal integer.
number::_is-positive-integer() {
  if [[ "$#" -ne 1 ]]; then
    return 64
  fi

  ( [[ "$1" =~ ^[1-9][0-9]*$ ]] )
}

### Test whether an unsigned decimal integer does not exceed a maximum.
number::_is-non-negative-integer-at-most() {
  if [[ "$#" -ne 2 ]] ||
    ! number::_is-non-negative-integer "$1" ||
    ! number::_is-positive-integer "$2"; then
    return 64
  fi

  local value="$1"
  local maximum="$2"
  local LC_ALL=C

  while [[ "${#value}" -gt 1 && "${value:0:1}" == '0' ]]; do
    value="${value:1}"
  done
  if [[ "${#value}" -lt "${#maximum}" ]]; then
    return 0
  fi
  if [[ "${#value}" -gt "${#maximum}" || "${value}" > "${maximum}" ]]; then
    return 1
  fi
  return 0
}

### Test whether a positive decimal integer does not exceed a maximum.
number::_is-positive-integer-at-most() {
  if [[ "$#" -ne 2 ]] || ! number::_is-positive-integer "$1"; then
    return 64
  fi

  number::_is-non-negative-integer-at-most "$1" "$2"
}

