### Require the current locale to use UTF-8.
string::_require-utf8-locale() {
  if [[ "$#" -ne 0 ]]; then
    return 64
  fi
  if ! command -v locale >/dev/null 2>&1; then
    console::_write-error 'A UTF-8 locale is required.'
    return 69
  fi

  local character_map=''
  character_map="$(locale charmap 2>/dev/null)" || {
    console::_write-error 'A UTF-8 locale is required.'
    return 69
  }
  case "${character_map}" in
    UTF-8 | UTF8 | utf-8 | utf8)
      return 0
      ;;
    *)
      console::_write-error 'A UTF-8 locale is required.'
      return 69
      ;;
  esac
}

### Remove leading and trailing whitespace.
string::trim() {
  if [[ "$#" -ne 1 ]]; then
    return 64
  fi

  local value="$1"
  local first=''
  local last=''

  while [[ -n "${value}" ]]; do
    first="${value:0:1}"
    if [[ "${first}" != [[:space:]] ]]; then
      break
    fi
    value="${value:1}"
  done

  while [[ -n "${value}" ]]; do
    last="${value:$((${#value} - 1)):1}"
    if [[ "${last}" != [[:space:]] ]]; then
      break
    fi
    value="${value:0:$((${#value} - 1))}"
  done

  printf '%s\n' "${value}"
}

### Trim whitespace and collapse each interior run to one ASCII space.
string::collapse-whitespace() {
  if [[ "$#" -ne 1 ]]; then
    return 64
  fi

  local value="$1"
  local result=''
  local character=''
  local whitespace='1'
  local index=''

  for ((index = 0; index < ${#value}; index++)); do
    character="${value:index:1}"
    if [[ "${character}" == [[:space:]] ]]; then
      whitespace='1'
    else
      if [[ "${whitespace}" -eq 1 && -n "${result}" ]]; then
        result+=' '
      fi
      result+="${character}"
      whitespace='0'
    fi
  done

  printf '%s\n' "${result}"
}

### Split a value by a non-empty literal delimiter and preserve empty fields.
string::split() {
