  while [[ "${value}" == *"${delimiter}"* ]]; do
    part="${value%%"${delimiter}"*}"
    printf '%s\n' "${part}"
    value="${value#*"${delimiter}"}"
  done
  printf '%s\n' "${value}"
}

### Translate ASCII letter case according to the requested mode.
string::_translate-ascii() {
  if [[ "$#" -ne 2 ]]; then
    return 64
  fi

  local value="$1"
  local mode="$2"
  local upper='ABCDEFGHIJKLMNOPQRSTUVWXYZ'
  local lower='abcdefghijklmnopqrstuvwxyz'
  local character=''
  local prefix=''
  local index=''
  local result=''
  local position=''
  local LC_ALL=C

  for ((position = 0; position < ${#value}; position++)); do
    character="${value:position:1}"
    case "${mode}:${character}" in
      lower:[A-Z])
        prefix="${upper%%"${character}"*}"
        index="${#prefix}"
        result+="${lower:index:1}"
        ;;
      upper:[a-z])
        prefix="${lower%%"${character}"*}"
        index="${#prefix}"
        result+="${upper:index:1}"
        ;;
      swap:[A-Z])
        prefix="${upper%%"${character}"*}"
        index="${#prefix}"
        result+="${lower:index:1}"
        ;;
      swap:[a-z])
        prefix="${lower%%"${character}"*}"
        index="${#prefix}"
        result+="${upper:index:1}"
        ;;
      *)
        result+="${character}"
        ;;
    esac
  done

  printf '%s\n' "${result}"
}

