### Percent-encode a UTF-8 string byte by byte.
string::encode-url() {
  if [[ "$#" -ne 1 ]]; then
    return 64
  fi

  local value="$1"
  local character=''
  local encoded=''
  local hex=''
  local code=''
  local index=''
  local LC_ALL=C

  for ((index = 0; index < ${#value}; index++)); do
    character="${value:index:1}"
    case "${character}" in
      [a-zA-Z0-9.~_-])
        encoded+="${character}"
        ;;
      *)
        printf -v code '%d' "'${character}"
        code="$((code & 255))"
        printf -v hex '%02X' "${code}"
        encoded+="%${hex}"
        ;;
    esac
  done

  printf '%s\n' "${encoded}"
}

### Decode percent-encoded bytes without translating plus signs.
string::decode-url() {
  if [[ "$#" -ne 1 ]]; then
    return 64
  fi

  local value="$1"
  local decoded=''
  local byte=''
  local hex=''
  local index='0'
  local LC_ALL=C

  while ((index < ${#value})); do
    if [[ "${value:index:1}" == '%' ]]; then
      if ((index + 2 >= ${#value})); then
        return 64
      fi
      hex="${value:index+1:2}"
      if ! ( [[ "${hex}" =~ ^[0-9A-Fa-f]{2}$ ]] ) || [[ "${hex}" == '00' ]]; then
        return 64
      fi
      printf -v byte '%b' "\\x${hex}"
      decoded+="${byte}"
      index=$((index + 3))
    else
      decoded+="${value:index:1}"
      index=$((index + 1))
    fi
  done

  printf '%s\n' "${decoded}"
}

