### Replace the rightmost non-empty substring that matches a Bash pattern.
string::replace-last() {
  if [[ "$#" -ne 3 || -z "$2" ]]; then
    return 64
  fi

  local value="$1"
  local pattern="$2"
  local replacement="$3"
  local candidate=''
  local matched=''
  local start=''
  local length=''

  for ((start = ${#value} - 1; start >= 0; start--)); do
    candidate="${value:start}"
    for ((length = ${#candidate}; length >= 1; length--)); do
      matched="${candidate:0:length}"
      # shellcheck disable=SC2053
      if [[ "${matched}" == ${pattern} ]]; then
        printf '%s%s%s\n' \
          "${value:0:start}" \
          "${replacement}" \
          "${candidate:length}"
        return 0
      fi
    done
  done

  printf '%s\n' "${value}"
}

