### Write a validated character range from a UTF-8 string.
string::slice() {
  if [[ "$#" -lt 2 || "$#" -gt 3 ]] ||
    ! number::_is-non-negative-integer-at-most "$2" 2147483647; then
    return 64
  fi
  string::_require-utf8-locale || return "$?"

  local value="$1"
  local start="$2"
  local end="${3-${#1}}"
  local length="${#value}"

  if ! number::_is-non-negative-integer-at-most "${end}" 2147483647; then
    return 64
  fi
  if ((10#${start} > 10#${end} || 10#${end} > length)); then
    return 64
  fi
  printf '%s\n' "${value:10#${start}:10#${end}-10#${start}}"
}


### Test a value against a Bash POSIX extended regular expression.
regex::is-match() {
  if [[ "$#" -ne 2 ]]; then
    return 64
  fi

  local value="$1"
  local expression="$2"
  local status=''

  # shellcheck disable=SC2233
  if ( [[ "${value}" =~ ${expression} ]] ); then
    return 0
  else
    status="$?"
  fi

  if [[ "${status}" -eq 2 ]]; then
    return 64
  fi
  return 1
}

### Write one capture group from a Bash POSIX extended regular expression.
regex::capture-group() {
  if [[ "$#" -ne 3 ]] ||
    ! number::_is-non-negative-integer-at-most "$3" 2147483647; then
    return 64
  fi

  local value="$1"
  local expression="$2"
  local group="$((10#$3))"

  (
    local status=''
    if [[ "${value}" =~ ${expression} ]]; then
      if ((group >= ${#BASH_REMATCH[@]})); then
        return 64
      fi
      if ! string::_require-one-line "${BASH_REMATCH[group]}"; then
        return 64
      fi
      printf '%s\n' "${BASH_REMATCH[group]}"
      return 0
    else
      # shellcheck disable=SC2319
      status="$?"
    fi
    if [[ "${status}" -eq 2 ]]; then
      return 64
    fi
    return 1
  )
}

### Write all capture groups from a Bash POSIX extended regular expression.
regex::capture-groups() {
  if [[ "$#" -ne 2 ]]; then
    return 64
  fi

  local value="$1"
  local expression="$2"

  (
    local status=''
    local index=''
    if [[ "${value}" =~ ${expression} ]]; then
      for ((index = 1; index < ${#BASH_REMATCH[@]}; index++)); do
        if ! string::_require-one-line "${BASH_REMATCH[index]}"; then
          return 64
        fi
        printf '%s\n' "${BASH_REMATCH[index]}"
      done
      return 0
    else
      # shellcheck disable=SC2319
      status="$?"
    fi
    if [[ "${status}" -eq 2 ]]; then
      return 64
    fi
    return 1
  )
}


### Test whether the remaining arguments contain the expected value.
array::contains() {
  if [[ "$#" -lt 1 ]]; then
    return 64
  fi

  local expected="$1"
  local value=''
  shift

  for value in "$@"; do
    if [[ "${value}" == "${expected}" ]]; then
      return 0
    fi
  done

  return 1
}

### Write the arguments in reverse order, one value per line.
array::reverse() {
  local values=("$@")
  local index=''

  for ((index = ${#values[@]} - 1; index >= 0; index--)); do
    if ! string::_require-one-line "${values[index]}"; then
      return 64
    fi
    printf '%s\n' "${values[index]}"
  done
}

### Write the number of arguments.
array::length() {
  printf '%s\n' "$#"
}

### Write the first argument when one is available.
array::first() {
  if [[ "$#" -eq 0 ]]; then
    return 1
  fi
  if ! string::_require-one-line "$1"; then
    return 64
  fi

  printf '%s\n' "$1"
}

### Write the last argument when one is available.
array::last() {
  if [[ "$#" -eq 0 ]]; then
    return 1
  fi

  local value=''
  for value in "$@"; do
    :
  done

  if ! string::_require-one-line "${value}"; then
    return 64
  fi
  printf '%s\n' "${value}"
}

### Write each distinct argument once in its original order.
array::unique() {
  local seen=()
  local value=''
  local previous=''
  local duplicate='0'

  for value in "$@"; do
    if ! string::_require-one-line "${value}"; then
      return 64
    fi

    duplicate='0'
    for previous in "${seen[@]}"; do
      if [[ "${previous}" == "${value}" ]]; then
        duplicate='1'
        break
      fi
    done

    if [[ "${duplicate}" -eq 0 ]]; then
      seen[${#seen[@]}]="${value}"
      printf '%s\n' "${value}"
    fi
  done
}

### Prefix every value and write one result per line.
array::prepend-to-each() {
  if [[ "$#" -lt 1 ]] || ! string::_require-one-line "$1"; then
    return 64
  fi

  local prefix="$1"
  local value=''
  shift

  for value in "$@"; do
    if ! string::_require-one-line "${value}"; then
      return 64
    fi
    printf '%s%s\n' "${prefix}" "${value}"
  done
}


### Require a value to follow the current named argument.
arg::require-next() {
