### Require a named argument value to match one candidate.
arg::one-of() {
  if [[ "$#" -lt 3 ]]; then
    return 64
  fi

  local name="$1"
  local value="$2"
  local candidate=''
  shift 2

  for candidate in "$@"; do
    if [[ "${value}" == "${candidate}" ]]; then
      return 0
    fi
  done

  console::_write-error "Option ${name} must be one of: $*. Got: ${value}"
  return 64
